from __future__ import annotations

import numpy as np


def mean_subtracted_vectors(activation_by_emotion: dict[str, np.ndarray]) -> dict[str, np.ndarray]:
    """Return emotion means minus the grand mean across emotion means."""
    if not activation_by_emotion:
        raise ValueError("activation_by_emotion must not be empty")
    keys = list(activation_by_emotion)
    stacked = np.stack([activation_by_emotion[k] for k in keys], axis=0)
    grand = stacked.mean(axis=0)
    return {k: activation_by_emotion[k] - grand for k in keys}


def pca_components_for_variance(x: np.ndarray, threshold: float = 0.5) -> np.ndarray:
    """Compute right-singular principal components explaining at least threshold variance."""
    if x.ndim != 2:
        raise ValueError("x must be a 2D matrix")
    if not 0 <= threshold <= 1:
        raise ValueError("threshold must be in [0, 1]")
    centered = x - x.mean(axis=0, keepdims=True)
    if np.allclose(centered, 0):
        return np.zeros((0, x.shape[1]), dtype=float)
    _, s, vt = np.linalg.svd(centered, full_matrices=False)
    variances = s**2
    total = variances.sum()
    if total <= 0:
        return np.zeros((0, x.shape[1]), dtype=float)
    cumulative = np.cumsum(variances) / total
    n = int(np.searchsorted(cumulative, threshold, side="left") + 1)
    return vt[:n]


def project_out_components(vectors: np.ndarray, components: np.ndarray) -> np.ndarray:
    """Remove the span of row-wise orthonormal components from vectors."""
    if components.size == 0:
        return vectors.copy()
    q, _ = np.linalg.qr(components.T)
    return vectors - (vectors @ q) @ q.T


def cosine_similarity_matrix(vectors: np.ndarray, activations: np.ndarray, eps: float = 1e-12) -> np.ndarray:
    v = vectors / np.maximum(np.linalg.norm(vectors, axis=1, keepdims=True), eps)
    a = activations / np.maximum(np.linalg.norm(activations, axis=1, keepdims=True), eps)
    return v @ a.T


def vector_norm_mean(x: np.ndarray) -> float:
    return float(np.linalg.norm(x, axis=-1).mean())
